import { formatJson } from '../datapack/text'
import type { ItemFormat } from './formats'
import {
  equipmentLayer,
  itemDefPath,
  itemRef,
  nameKey,
  type ArmorSlot,
  type CustomItem,
  type ItemRecipe
} from './schema'

/**
 * Game files of a custom item for one Minecraft version (PLAN M14). Pure: the same definition and format always give
 * the same text, which is how the Pack Doctor spots generated files edited by hand.
 */

export interface GeneratedFile {
  path: string
  text: string
}

/** Header of the give function (Minecraft ignores lines starting with "#"). */
const FUNCTION_HEADER = '# Generated by Blocksmith Studio from blocksmith/items/'

const ARMOR_PIECE: Record<ArmorSlot, string> = {
  head: 'helmet',
  chest: 'chestplate',
  legs: 'leggings',
  feet: 'boots'
}

/** Rounds away float noise (0.1 + 0.2) so files stay stable and readable. */
function num(n: number): number {
  return Math.round(n * 10000) / 10000
}

/** A text component: an object from 1.21.5, a string holding JSON before. */
function text(format: ItemFormat, component: Record<string, unknown>): unknown {
  return format.textAsObject ? component : JSON.stringify(component)
}

function attributeModifiers(item: CustomItem): Array<Record<string, unknown>> {
  const list: Array<Record<string, unknown>> = []
  if (item.weapon) {
    // Vanilla ids: the tooltip shows them as the item's base stats ("7 Attack Damage"), the player's own 1 and 4
    // included, so the amounts are relative to those.
    list.push(
      {
        type: 'minecraft:attack_damage',
        id: 'minecraft:base_attack_damage',
        amount: num(item.weapon.attackDamage - 1),
        operation: 'add_value',
        slot: 'mainhand'
      },
      {
        type: 'minecraft:attack_speed',
        id: 'minecraft:base_attack_speed',
        amount: num(item.weapon.attackSpeed - 4),
        operation: 'add_value',
        slot: 'mainhand'
      }
    )
  }
  if (item.armor) {
    const { slot } = item.armor
    const id = `minecraft:armor.${ARMOR_PIECE[slot]}`
    list.push({
      type: 'minecraft:armor',
      id,
      amount: num(item.armor.armor),
      operation: 'add_value',
      slot
    })
    if (item.armor.toughness > 0) {
      list.push({
        type: 'minecraft:armor_toughness',
        id,
        amount: num(item.armor.toughness),
        operation: 'add_value',
        slot
      })
    }
    if (item.armor.knockbackResistance > 0) {
      list.push({
        type: 'minecraft:knockback_resistance',
        id,
        amount: num(item.armor.knockbackResistance),
        operation: 'add_value',
        slot
      })
    }
  }
  return list
}

/**
 * The components the item carries on top of its base item, in a stable order. Removed components are
 * `"!minecraft:x": {}` (the patch syntax of recipe results and loot functions).
 */
export function itemComponents(item: CustomItem, format: ItemFormat): Record<string, unknown> {
  const key = nameKey(item)
  const c: Record<string, unknown> = {
    'minecraft:item_model': itemRef(item),
    'minecraft:item_name': text(format, { translate: key, fallback: item.names['en_us'] })
  }
  if (item.lore.length > 0) {
    c['minecraft:lore'] = item.lore.map((line, i) =>
      text(format, {
        translate: `${key}.lore.${i + 1}`,
        fallback: line['en_us'],
        color: 'gray',
        italic: false
      })
    )
  }
  if (item.rarity) c['minecraft:rarity'] = item.rarity
  if (item.glint !== undefined) c['minecraft:enchantment_glint_override'] = item.glint
  if (item.maxStack !== undefined) c['minecraft:max_stack_size'] = item.maxStack
  if (item.durability !== undefined) {
    c['minecraft:max_damage'] = item.durability
    // A damageable item cannot stack; say it even when the base item stacks.
    if (item.maxStack === undefined) c['minecraft:max_stack_size'] = 1
  }
  if (item.repairWith) c['minecraft:repairable'] = { items: item.repairWith }
  if (item.enchantability !== undefined) {
    c['minecraft:enchantable'] = { value: item.enchantability }
  }
  if (item.food) {
    const f = item.food
    c['minecraft:food'] = {
      nutrition: f.nutrition,
      saturation: num(f.saturation),
      can_always_eat: f.alwaysEdible
    }
    const drink = f.animation === 'drink'
    c['minecraft:consumable'] = {
      consume_seconds: num(f.eatSeconds),
      animation: f.animation,
      sound: drink ? 'minecraft:entity.generic.drink' : 'minecraft:entity.generic.eat',
      has_consume_particles: !drink,
      on_consume_effects: f.effects.map((e) => ({
        type: 'minecraft:apply_effects',
        effects: [{ id: e.effect, amplifier: e.level - 1, duration: Math.round(e.seconds * 20) }],
        probability: num(e.chance)
      }))
    }
  }
  if (item.tool) {
    const t = item.tool
    c['minecraft:tool'] = {
      rules: [
        { blocks: `#minecraft:incorrect_for_${t.tier}_tool`, correct_for_drops: false },
        {
          blocks: `#minecraft:mineable/${t.type}`,
          correct_for_drops: true,
          speed: num(t.miningSpeed)
        }
      ],
      damage_per_block: 1
    }
  }
  const modifiers = attributeModifiers(item)
  if (modifiers.length > 0) {
    c['minecraft:attribute_modifiers'] = format.modifiersAsList
      ? modifiers
      : { modifiers, show_in_tooltip: true }
  }
  if (item.armor) {
    c['minecraft:equippable'] = { slot: item.armor.slot, asset_id: itemRef(item) }
  }
  for (const id of item.removeComponents) {
    if (!(id in c)) c[`!${id}`] = {}
  }
  for (const [id, value] of Object.entries(item.extraComponents)) {
    // An extra component wins over the generated one (and over its removal).
    delete c[id.startsWith('!') ? id.slice(1) : `!${id}`]
    c[id] = value
  }
  return c
}

/** Shaped grid -> Minecraft pattern + key, trimmed to the used rows and columns; keys are A, B, C... */
function shapedPattern(grid: ReadonlyArray<string | null>): {
  pattern: string[]
  key: Record<string, string>
} {
  const cell = (r: number, col: number): string | null => grid[r * 3 + col] ?? null
  const rows = [0, 1, 2].filter((r) => [0, 1, 2].some((col) => cell(r, col) !== null))
  const cols = [0, 1, 2].filter((col) => [0, 1, 2].some((r) => cell(r, col) !== null))
  const r0 = Math.min(...rows)
  const r1 = Math.max(...rows)
  const c0 = Math.min(...cols)
  const c1 = Math.max(...cols)
  const letters = new Map<string, string>()
  const pattern: string[] = []
  for (let r = r0; r <= r1; r++) {
    let line = ''
    for (let col = c0; col <= c1; col++) {
      const ingredient = cell(r, col)
      if (ingredient === null) {
        line += ' '
        continue
      }
      let letter = letters.get(ingredient)
      if (!letter) {
        letter = String.fromCharCode(65 + letters.size)
        letters.set(ingredient, letter)
      }
      line += letter
    }
    pattern.push(line)
  }
  return { pattern, key: Object.fromEntries([...letters].map(([id, l]) => [l, id])) }
}

function recipeJson(
  item: CustomItem,
  recipe: ItemRecipe,
  components: Record<string, unknown>
): unknown {
  const category = ['weapon', 'tool', 'armor'].includes(item.kind) ? 'equipment' : 'misc'
  const result = { id: item.base, count: recipe.count, components }
  if (recipe.type === 'shaped') {
    const { pattern, key } = shapedPattern(recipe.grid)
    return { type: 'minecraft:crafting_shaped', category, pattern, key, result }
  }
  return {
    type: 'minecraft:crafting_shapeless',
    category,
    ingredients: recipe.ingredients,
    result
  }
}

/** A JSON value as SNBT (command syntax). Booleans are SNBT `true` / `false` (bytes). */
export function toSnbt(value: unknown): string {
  if (value === null || value === undefined) return '{}'
  if (typeof value === 'boolean') return value ? 'true' : 'false'
  if (typeof value === 'number') return String(num(value))
  if (typeof value === 'string') {
    if (value.includes('"') && !value.includes("'")) return `'${value.replace(/\\/g, '\\\\')}'`
    return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`
  }
  if (Array.isArray(value)) return `[${value.map(toSnbt).join(',')}]`
  const entries = Object.entries(value as Record<string, unknown>).map(([k, v]) => {
    const key = /^[A-Za-z0-9._+-]+$/.test(k)
      ? k
      : `"${k.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`
    return `${key}:${toSnbt(v)}`
  })
  return `{${entries.join(',')}}`
}

/** The item as a command argument: `minecraft:stone_sword[minecraft:item_model="my_pack:ruby_sword",...]`. */
export function itemStackArgument(item: CustomItem, format: ItemFormat): string {
  const parts = Object.entries(itemComponents(item, format)).map(([id, value]) =>
    id.startsWith('!') ? id : `${id}=${toSnbt(value)}`
  )
  return `${item.base}[${parts.join(',')}]`
}

/** The /give command a player (with cheats) types to get the item. */
export function giveCommand(item: CustomItem, format: ItemFormat): string {
  return `/give @s ${itemStackArgument(item, format)}`
}

/** `/function <ns>:give/<id>`: runs the generated give function. */
export function functionCommand(item: CustomItem): string {
  return `/function ${item.namespace}:give/${item.id}`
}

/** `data/<ns>/function/give_all.mcfunction`: gives every custom item of the namespace (outside `give/`, so no item
 * id can collide with it). */
export function giveAllPath(namespace: string): string {
  return `data/${namespace}/function/give_all.mcfunction`
}

/** `/function <ns>:give_all` */
export function giveAllCommand(namespace: string): string {
  return `/function ${namespace}:give_all`
}

/** The give_all function of a namespace (calls each item's give function, by id); null when it has no item. */
export function giveAllFile(namespace: string, items: readonly CustomItem[]): GeneratedFile | null {
  const ids = items
    .filter((i) => i.namespace === namespace)
    .map((i) => i.id)
    .sort()
  if (ids.length === 0) return null
  const calls = ids.map((id) => `function ${namespace}:give/${id}\n`).join('')
  return {
    path: giveAllPath(namespace),
    text: `# Generated by Blocksmith Studio: gives every custom item of ${namespace}\n${calls}`
  }
}

/** Paths of the generated files (lang files aside: they are shared by every item of the namespace). */
export function generatedPaths(item: CustomItem): string[] {
  const ns = item.namespace
  const paths = [`assets/${ns}/items/${item.id}.json`, `assets/${ns}/models/item/${item.id}.json`]
  if (item.armor) paths.push(`assets/${ns}/equipment/${item.id}.json`)
  if (item.recipe) paths.push(`data/${ns}/recipe/${item.id}.json`)
  paths.push(`data/${ns}/function/give/${item.id}.mcfunction`)
  return paths
}

/** Every generated file of the item except the lang files (see langEntries). */
export function generateItemFiles(item: CustomItem, format: ItemFormat): GeneratedFile[] {
  const ns = item.namespace
  const ref = itemRef(item)
  const components = itemComponents(item, format)
  const files: GeneratedFile[] = [
    {
      path: `assets/${ns}/items/${item.id}.json`,
      text: formatJson({ model: { type: 'minecraft:model', model: `${ns}:item/${item.id}` } })
    },
    {
      path: `assets/${ns}/models/item/${item.id}.json`,
      text: formatJson({
        parent: item.handheld ? 'minecraft:item/handheld' : 'minecraft:item/generated',
        textures: { layer0: `${ns}:item/${item.id}` }
      })
    }
  ]
  if (item.armor) {
    files.push({
      path: `assets/${ns}/equipment/${item.id}.json`,
      text: formatJson({ layers: { [equipmentLayer(item.armor.slot)]: [{ texture: ref }] } })
    })
  }
  if (item.recipe) {
    files.push({
      path: `data/${ns}/recipe/${item.id}.json`,
      text: formatJson(recipeJson(item, item.recipe, components))
    })
  }
  files.push({
    path: `data/${ns}/function/give/${item.id}.mcfunction`,
    text: `${FUNCTION_HEADER}${item.id}.json\ngive @s ${itemStackArgument(item, format)}\n`
  })
  return files
}

/** `assets/<ns>/lang/<lang>.json` */
export function langPath(namespace: string, lang: string): string {
  return `assets/${namespace}/lang/${lang}.json`
}

/** Name and lore texts per language: { en_us: { "item.my_pack.ruby": "Ruby" } }. */
export function langEntries(item: CustomItem): Record<string, Record<string, string>> {
  const key = nameKey(item)
  const out: Record<string, Record<string, string>> = {}
  for (const [lang, name] of Object.entries(item.names)) (out[lang] ??= {})[key] = name
  item.lore.forEach((line, i) => {
    for (const [lang, value] of Object.entries(line)) {
      ;(out[lang] ??= {})[`${key}.lore.${i + 1}`] = value
    }
  })
  return out
}

/** True for the lang keys the item owns (its name and lore lines). */
export function ownsLangKey(item: Pick<CustomItem, 'namespace' | 'id'>, key: string): boolean {
  const own = nameKey(item)
  return key === own || key.startsWith(`${own}.lore.`)
}

/**
 * The lang files of a namespace after `items` are written and `dropped` removed: their keys are replaced, the other
 * keys of each file are kept. `read` returns a lang file's current object (null when absent). A file left with no
 * key is removed (null).
 */
export function updateLangFiles(
  namespace: string,
  items: readonly CustomItem[],
  dropped: ReadonlyArray<Pick<CustomItem, 'namespace' | 'id'>>,
  read: (path: string) => Record<string, string> | null,
  langs: Iterable<string>
): Array<{ path: string; text: string | null }> {
  const mine = items.filter((i) => i.namespace === namespace)
  const owners = [...mine, ...dropped.filter((d) => d.namespace === namespace)]
  const wanted = new Map<string, Record<string, string>>()
  for (const item of mine) {
    for (const [lang, entries] of Object.entries(langEntries(item))) {
      wanted.set(lang, { ...wanted.get(lang), ...entries })
    }
  }
  const all = new Set([...langs, ...wanted.keys()])
  const out: Array<{ path: string; text: string | null }> = []
  for (const lang of [...all].sort()) {
    const path = langPath(namespace, lang)
    const current = read(path)
    const next: Record<string, string> = {}
    for (const [k, v] of Object.entries(current ?? {})) {
      if (!owners.some((o) => ownsLangKey(o, k))) next[k] = v
    }
    Object.assign(next, wanted.get(lang) ?? {})
    const sorted = Object.fromEntries(Object.entries(next).sort(([a], [b]) => (a < b ? -1 : 1)))
    if (Object.keys(sorted).length === 0) {
      if (current !== null) out.push({ path, text: null })
      continue
    }
    const textOut = formatJson(sorted)
    if (current === null || formatJson(current) !== textOut) out.push({ path, text: textOut })
  }
  return out
}

/** The definition file text (normalized, defaults included). */
export function itemDefinitionText(item: CustomItem): { path: string; text: string } {
  return { path: itemDefPath(item.id), text: formatJson(item) }
}
